SELECT CAST(COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_rate FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE a.gender = 'F' AND p.age BETWEEN 83 AND 93 AND a.admission_type = 'Pneumonia' AND a.hadm_id IN (SELECT MIN(hadm_id) FROM admissions WHERE subject_id = a.subject_id);